function makeScoreRow ()
  local scoreRowTable = {}
     for id=1,4,1 do
     	table.insert(scoreRowTable, {
           tag = "Row",
           attributes = {
            id = "ScoreRow" .. id,
            class = "ScoreTableRow",
            dontUseTableRowBackground = "true",
            visibility = "nil",
            color = "",
            outline = "",
            outlineSize = "5 5",
           },
           children = {
            {
             tag = "Cell",
             attributes = {
             },
             children = {
              {
               tag = "Text",
               value = "Player " .. id,
               attributes = {
                id = "playerID"  .. id,
               },
              },
             },
            },
            {
             tag = "Cell",
             attributes = {
