function xmlHelper()
	for i, player in pairs(players) do
	table.insert(xmlTable, #xmlTable+1, {
  tag = "Panel",
  attributes = {
   id = "helper" .. player,
   class = "WindowBorder",
   width = "700",
   height = "50",
   offsetXY = "500 0",
   rectAlignment = "LowerCenter",
   showAnimation = "Grow",
   visibility = "nil",
   active = "true",
  },
  children = {
   {
    tag = "HorizontalLayout",
    attributes = {
     childForceExpandWidth = "false",
     childAlignment = "MiddleCenter",
    },
    children = prepXmlHelperElements(player)
			}
		}
	})
  table.insert(xmlTable, #xmlTable+1, {
    tag = "Button",
    value = "Hide",
    attributes = {
     id = "button" .. player,
     fontStyle = "bold",
     fontSize = "30",
     offsetXY = "800 5",
     rectAlignment = "LowerCenter",
     alignment = "MiddleRight",
     visibility = "nil",
     onClick = "helperOnClick(on)",
     color = "",
     width = "100",
     height = "40",
    },
  })
	end
end

function prepXmlHelperElements(player)
	local tempXmlHelperElements = {}
	for name, color in pairs(colors) do
	if name == 'j' then
	table.insert(tempXmlHelperElements, #tempXmlHelperElements + 1, {
      tag = "Text",
      value = "0",
      attributes = {
       id = name .. "GemCount" .. player,
       fontStyle = "bold",
       fontSize = "40",
       color = color,
      },
      children = {
      },
    })
	else
	table.insert(tempXmlHelperElements, #tempXmlHelperElements + 1,
	  {
      tag = "Text",
      value = "0",
      attributes = {
       id = name .. "GemCount" .. player,
       fontStyle = "bold",
       fontSize = "40",
       color = color,
      },
    })
	 table.insert(tempXmlHelperElements, #tempXmlHelperElements + 1, {
      tag = "Text",
      value = "(",
      attributes = {
       fontSize = "40",
       color = color,
      },
    })
     table.insert(tempXmlHelperElements, #tempXmlHelperElements + 1, {
      tag = "Text",
      value = "0",
      attributes = {
       id = name .. "CardCount" .. player,
       fontStyle = "bold",
       fontSize = "40",
       color = color,
      },
    })
     table.insert(tempXmlHelperElements, #tempXmlHelperElements + 1, {
      tag = "Text",
      value = ")",
      attributes = {
       fontSize = "40",
       color = color,
      },
    })
     table.insert(tempXmlHelperElements, #tempXmlHelperElements + 1, {
      tag = "Text",
      value = "a",
      attributes = {
       fontSize = "40",
       color = "#00000000",
      },
    })
	end
end
  return tempXmlHelperElements
end

function makeXmlTable()
